def norm(x):
    return re.sub(r'\s+', ' ', str(x).lower()).strip()

def add_ids(dst, src):
    for x in src:
        if x not in dst:
            dst.append(x)
    return dst

def make_windows(spans):
    out = []
    n = len(spans)
    for size in range(1, 4):
        for i in range(0, n - size + 1):
            ids = []
            parts = []
            for j in range(i, i + size):
                ids.append(spans[j].get('id'))
                parts.append(norm(spans[j].get('text', '')))
            out.append((ids, ' '.join(parts)))
    return out

def role_flags(t):
    employee = bool(re.search(r'\b(?:employees?|staff|personnel)\b', t))
    external = bool(re.search(r'\b(?:third[- ]part(?:y|ies)|consultants?|agents?|advis(?:e|o)rs?|accountants?|attorneys?|lawyers?|legal counsel|outside counsel|auditors?|contractors?|lenders?|financing sources?|professional advisers?|affiliates?)\b', t))
    representative = bool(re.search(r'\brepresentatives?\b', t))
    return employee, external, representative

def is_rep_definition(t):
    if not re.search(r'\brepresentatives?\b', t):
        return False
    return bool(re.search(r'\brepresentatives?\b.{0,28}\b(?:means?|shall mean|includes?|refer(?:s|red)? to)\b', t) or re.search(r'\([\s\"\']*representatives?[\s\"\']*\)', t))

def actor_ok(t, pos, tail):
    p = t[max(0, pos - 240):pos]
    good = max(p.rfind('receiving party'), p.rfind('recipient'), p.rfind('each party'), p.rfind('either party'), p.rfind('volunteer'), p.rfind('neither it nor its representatives'))
    bad = max(p.rfind('disclosing party'), p.rfind('originating party'))
    if bad >= 0 and bad > good:
        return False
    if good >= 0:
        return True
    if re.search(r'\b(?:the|a) party\s+(?:hereby\s+)?$', p):
        return True
    if re.search(r'\bby\s+(?:the\s+)?(?:receiving party|recipient)\b', tail[:160]):
        return True
    return False

def target_cut(s):
    end = min(len(s), 450)
    for d in [' provided that ', ' provided, however', ' subject to ', ' on condition ', ', each ', ' who have ', ' who need ', ' but only ', ';', '.']:
        p = s.find(d)
        if p >= 20 and p < end:
            end = p
    return s[:end]

def permission_targets(t):
    out = []
    pats = [
        r'\b(?:may|can)\s+(?:be\s+)?(?:disclose|disclosed|share|shared|provide|provided|release|released|transmit|transmitted|give|given|make available|allow access)\b',
        r'\b(?:is|are|shall be|will be)\s+(?:expressly\s+)?(?:permitted|authorized|allowed)\s+to\s+(?:disclose|share|provide|release|transmit|give|make available|allow access)\b'
    ]
    for pat in pats:
        for m in re.finditer(pat, t):
            tail = t[m.end():]
            near = t[max(0, m.start() - 140):m.end() + 260]
            if not re.search(r'\b(?:confidential information|confidential materials?|such information|such confidential information)\b', near):
                continue
            if actor_ok(t, m.start(), tail):
                out.append(target_cut(tail))
    epat = r'\b(?:shall|will|must)\s+not\b[^.;]{0,240}\b(?:disclose|share|provide|divulge|communicate|release|transmit)\b[^.;]{0,240}\bexcept\s+to\b'
    for m in re.finditer(epat, t):
        tail = t[m.end():]
        near = t[max(0, m.start() - 100):m.end()]
        if re.search(r'\b(?:confidential information|confidential materials?|such information)\b', near) and actor_ok(t, m.start(), tail):
            out.append(target_cut(tail))
    return out

def wrong_employee_owner(t):
    return bool(re.search(r'\b(?:disclosing|originating|other)\s+party[\'’]?s\s+(?:directors?[, ]+|officers?[, ]+|representatives?[, ]+)*employees?\b', t) or re.search(r'\bemployees?\s+of\s+(?:the\s+)?(?:disclosing|originating|other)\s+party\b', t))

def wrong_rep_owner(t):
    return bool(re.search(r'\b(?:disclosing|originating|other)\s+party[\'’]?s\s+representatives?\b', t) or re.search(r'\brepresentatives?\s+of\s+(?:the\s+)?(?:disclosing|originating|other)\s+party\b', t))

def prohibition_actor_ok(t, pos):
    p = t[max(0, pos - 220):pos]
    if 'neither it nor its representatives' in p:
        return True
    good = max(p.rfind('receiving party'), p.rfind('recipient'), p.rfind('each party'), p.rfind('either party'), p.rfind('volunteer'))
    bad = max(p.rfind('disclosing party'), p.rfind('originating party'))
    rep = p.rfind('representative')
    if bad >= 0 and bad > good:
        return False
    if rep > good:
        return False
    return good >= 0

def functional_exception(t):
    return bool(re.search(r'\bexcept\b[^.;]{0,150}\b(?:required|necessary)\b[^.;]{0,110}\b(?:purpose|business relationship|obligations?|service)\b', t))

def contradiction_proof(windows, task_id):
    if task_id == 'nda-7':
        pats = [
            r'\b(?:shall|will|must|may)\s+not\b[^.;]{0,150}\b(?:disclose|share|divulge|communicate|provide|release|transmit)\b[^.;]{0,210}\b(?:third[- ]part(?:y|ies)|any other person|any other organization)\b',
            r'\b(?:agrees?\s+not\s+to|prohibited\s+from)\b[^.;]{0,190}\b(?:disclose|share|divulge|communicate|provide|release|transmit)\b[^.;]{0,210}\b(?:third[- ]part(?:y|ies)|any other person|any other organization)\b',
            r'\bneither\b[^.;]{0,120}\bwill\b[^.;]{0,210}\b(?:disclose|divulge|communicate)\b[^.;]{0,210}\b(?:third[- ]part(?:y|ies)|any other person|any other organization)\b'
        ]
    else:
        pats = [
            r'\b(?:shall|will|must|may)\s+not\b[^.;]{0,150}\b(?:disclose|share|divulge|communicate|provide|release|transmit)\b[^.;]{0,210}\b(?:its|their|the receiving party[\'’]?s)?\s*employees?\b',
            r'\b(?:agrees?\s+not\s+to|prohibited\s+from)\b[^.;]{0,190}\b(?:disclose|share|divulge|communicate|provide|release|transmit)\b[^.;]{0,210}\b(?:its|their|the receiving party[\'’]?s)?\s*employees?\b'
        ]
    for ids, t in windows:
        if not re.search(r'\b(?:confidential information|confidential materials?|such information)\b', t):
            continue
        for pat in pats:
            for m in re.finditer(pat, t):
                area = t[m.start():m.end() + 260]
                if prohibition_actor_ok(t, m.start()) and not functional_exception(area):
                    return ids
    return []

def relevant_ids(spans, task_id):
    out = []
    for s in spans:
        t = norm(s.get('text', ''))
        emp, ext, rep = role_flags(t)
        verb = bool(re.search(r'\b(?:disclose|share|divulge|communicate|provide|release|transmit|allow access)\b', t))
        specific = emp or rep if task_id == 'nda-5' else ext or rep
        if (specific and (verb or is_rep_definition(t))) or (verb and 'confidential' in t):
            add_ids(out, [s.get('id')])
            if len(out) >= 12:
                break
    if not out:
        for s in spans:
            add_ids(out, [s.get('id')])
    return out

def apply(inputs, premises):
    task_id = inputs.get('task_id') if isinstance(inputs, dict) else None
    if task_id not in ['nda-5', 'nda-7'] or not isinstance(premises, dict):
        return {'handled': False, 'answer': None, 'used_span_ids': []}
    spans = premises.get('source_spans')
    if not isinstance(spans, list):
        return {'handled': False, 'answer': None, 'used_span_ids': []}
    windows = make_windows(spans)
    definitions = []
    for s in spans:
        t = norm(s.get('text', ''))
        if is_rep_definition(t):
            emp, ext, rep = role_flags(t)
            definitions.append((s.get('id'), emp, ext))
    ent5 = []
    ent7 = []
    for ids, t in windows:
        targets = permission_targets(t)
        for target in targets:
            emp, ext, rep = role_flags(target)
            wrong_emp = wrong_employee_owner(target)
            wrong_rep = wrong_rep_owner(target)
            proof5 = list(ids)
            proof7 = list(ids)
            employee_ok = emp and not wrong_emp
            external_ok = ext or wrong_emp or wrong_rep
            if rep:
                for did, demp, dext in definitions:
                    if not employee_ok and not wrong_rep and demp:
                        employee_ok = True
                        add_ids(proof5, [did])
                    if not external_ok and dext:
                        external_ok = True
                        add_ids(proof7, [did])
            if employee_ok and not ent5:
                ent5 = proof5
            if external_ok and not ent7:
                ent7 = proof7
    if task_id == 'nda-5' and ent5:
        return {'handled': True, 'answer': 'Entailment', 'used_span_ids': ent5}
    if task_id == 'nda-7' and ent7:
        return {'handled': True, 'answer': 'Entailment', 'used_span_ids': ent7}
    contra = contradiction_proof(windows, task_id)
    if contra:
        return {'handled': True, 'answer': 'Contradiction', 'used_span_ids': contra}
    return {'handled': True, 'answer': 'NotMentioned', 'used_span_ids': relevant_ids(spans, task_id)}
